package apply_test

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	userv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/identity/user/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-org/internal/apply"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-org/internal/legacy"
)

// --- Membership-loop fakes -------------------------------------------------

type fakeMemReader struct {
	pages [][]legacy.UserOrganization // returned in order; subsequent calls get empty
	calls int
	err   error
}

func (f *fakeMemReader) ListUserOrganizations(_ context.Context, _, _ int64, _ int) ([]legacy.UserOrganization, error) {
	if f.err != nil {
		return nil, f.err
	}
	defer func() { f.calls++ }()
	if f.calls < len(f.pages) {
		return f.pages[f.calls], nil
	}
	return nil, nil
}

type fakeTenantLookup struct {
	resp *tenantv1.GetByLegacyIdResponse
	err  error
}

func (f *fakeTenantLookup) GetByLegacyId(_ context.Context, _ *tenantv1.GetByLegacyIdRequest) (*tenantv1.GetByLegacyIdResponse, error) {
	return f.resp, f.err
}

type fakeIdentityLookup struct {
	// errsByLegacyID lets a test specify a per-user-id error.
	// Default response (when no error matches) is the success below.
	errsByLegacyID map[string]error
	resp           *userv1.GetByLegacyIdResponse
	calls          int
}

func (f *fakeIdentityLookup) GetByLegacyId(_ context.Context, req *userv1.GetByLegacyIdRequest) (*userv1.GetByLegacyIdResponse, error) {
	f.calls++
	if err, ok := f.errsByLegacyID[req.GetLegacyId().GetValue()]; ok {
		return nil, err
	}
	return f.resp, nil
}

type fakeMembers struct {
	// errs is consumed in order across calls; once exhausted, the
	// last value sticks (matches fakeTarget in tenants_test).
	errs    []error
	resp    *tenantv1.AddMemberResponse
	calls   int
	lastReq *tenantv1.AddMemberRequest
}

func (f *fakeMembers) AddMember(_ context.Context, req *tenantv1.AddMemberRequest) (*tenantv1.AddMemberResponse, error) {
	f.lastReq = req
	idx := f.calls
	if idx >= len(f.errs) {
		idx = len(f.errs) - 1
	}
	f.calls++
	if idx < 0 || f.errs[idx] == nil {
		return f.resp, nil
	}
	return nil, f.errs[idx]
}

// --- Helpers ----------------------------------------------------------------

// cursorMemReader mirrors the real legacy.Reader's cursor semantics
// (rows whose ID is strictly greater than `cursor`, in ID order,
// capped at `limit`). The default fakeMemReader ignores the cursor,
// which hides the issue #53 plan-mode infinite loop.
type cursorMemReader struct {
	rows  []legacy.UserOrganization
	calls int
}

func (c *cursorMemReader) ListUserOrganizations(_ context.Context, _, cursor int64, limit int) ([]legacy.UserOrganization, error) {
	c.calls++
	out := make([]legacy.UserOrganization, 0, limit)
	for _, r := range c.rows {
		if r.ID <= cursor {
			continue
		}
		out = append(out, r)
		if len(out) >= limit {
			break
		}
	}
	return out, nil
}

func sampleMemberships() []legacy.UserOrganization {
	now := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
	return []legacy.UserOrganization{
		{ID: 100, UserID: 11, OrganizationID: 42, Role: "admin", IsActive: true, JoinedAt: now},
		{ID: 101, UserID: 12, OrganizationID: 42, Role: "operator", IsActive: true, JoinedAt: now},
		{ID: 102, UserID: 13, OrganizationID: 42, Role: "viewer", IsActive: true, JoinedAt: now},
	}
}

func tenantOK(uuid string) *fakeTenantLookup {
	return &fakeTenantLookup{
		resp: &tenantv1.GetByLegacyIdResponse{
			Tenant: &tenantv1.Tenant{
				Id: uuid,
				LegacyId: &commonv1.LegacyID{Value: "42"},
			},
		},
	}
}

func identityOK(uuid string) *fakeIdentityLookup {
	return &fakeIdentityLookup{
		resp: &userv1.GetByLegacyIdResponse{
			User: &userv1.User{Id: uuid},
		},
	}
}

func newMemberships(
	t *testing.T,
	r *fakeMemReader,
	tl *fakeTenantLookup,
	il *fakeIdentityLookup,
	ma *fakeMembers,
	c *fakeCursor,
	rep *fakeReporter,
	met *fakeMetrics,
	dryRun bool,
) *apply.Memberships {
	t.Helper()
	m, err := apply.NewMemberships(apply.MembershipsConfig{
		Reader:    r,
		Tenants:   tl,
		Identity:  il,
		Members:   ma,
		Cursor:    c,
		Reporter:  rep,
		Metrics:   met,
		RunID:     "run-test",
		TenantID:  42,
		BatchSize: 100,
		DryRun:    dryRun,
		Retry:     &apply.RetryPolicy{MaxAttempts: 5, Sleep: noSleep},
	})
	require.NoError(t, err)
	return m
}

// --- Cases ------------------------------------------------------------------

func TestMemberships_HappyPath_AppliesAllRows(t *testing.T) {
	r := &fakeMemReader{pages: [][]legacy.UserOrganization{sampleMemberships()}}
	tl := tenantOK("tenant-uuid")
	il := identityOK("user-uuid")
	ma := &fakeMembers{resp: &tenantv1.AddMemberResponse{}, errs: []error{nil}}
	c := &fakeCursor{}
	rep := &fakeReporter{}
	met := newFakeMetrics()

	sum, err := newMemberships(t, r, tl, il, ma, c, rep, met, false).Run(context.Background())
	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 3, Applied: 3}, sum)
	require.Equal(t, 3, ma.calls)
	require.Equal(t, int64(102), c.put, "cursor advanced to last row's id")
	require.Equal(t, 3, c.putCalls, "cursor advances per row, not per batch")
	require.Equal(t, 3, met.applied["created"])
	require.Empty(t, rep.rows)
}

func TestMemberships_UserNotMigrated_RejectsAndContinues(t *testing.T) {
	r := &fakeMemReader{pages: [][]legacy.UserOrganization{sampleMemberships()}}
	tl := tenantOK("tenant-uuid")
	il := &fakeIdentityLookup{
		resp: &userv1.GetByLegacyIdResponse{User: &userv1.User{Id: "user-uuid"}},
		errsByLegacyID: map[string]error{
			"12": status.Error(codes.NotFound, "user not migrated"),
		},
	}
	ma := &fakeMembers{resp: &tenantv1.AddMemberResponse{}, errs: []error{nil}}
	c := &fakeCursor{}
	rep := &fakeReporter{}
	met := newFakeMetrics()

	sum, err := newMemberships(t, r, tl, il, ma, c, rep, met, false).Run(context.Background())
	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 3, Applied: 2, Rejected: 1}, sum)
	require.Equal(t, 2, ma.calls, "AddMember NOT called for user_id=12")
	require.Len(t, rep.rows, 1)
	require.Equal(t, "USER_NOT_MIGRATED", rep.rows[0].ErrorCode)
	require.Equal(t, "101", rep.rows[0].LegacyID, "rejected row's user_organizations.id")
}

func TestMemberships_AddMemberAlreadyExists_Upserts(t *testing.T) {
	r := &fakeMemReader{pages: [][]legacy.UserOrganization{sampleMemberships()[:1]}}
	tl := tenantOK("tenant-uuid")
	il := identityOK("user-uuid")
	ma := &fakeMembers{errs: []error{status.Error(codes.AlreadyExists, "duplicate")}}
	c := &fakeCursor{}
	rep := &fakeReporter{}
	met := newFakeMetrics()

	sum, err := newMemberships(t, r, tl, il, ma, c, rep, met, false).Run(context.Background())
	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 1, Applied: 1}, sum)
	require.Equal(t, 1, met.applied["upserted"])
}

func TestMemberships_AddMemberInvalidArgument_RejectsAndContinues(t *testing.T) {
	r := &fakeMemReader{pages: [][]legacy.UserOrganization{sampleMemberships()[:2]}}
	tl := tenantOK("tenant-uuid")
	il := identityOK("user-uuid")
	ma := &fakeMembers{errs: []error{
		status.Error(codes.InvalidArgument, "bad role"),
		nil,
	}}
	c := &fakeCursor{}
	rep := &fakeReporter{}
	met := newFakeMetrics()

	sum, err := newMemberships(t, r, tl, il, ma, c, rep, met, false).Run(context.Background())
	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 2, Applied: 1, Rejected: 1}, sum)
	require.Len(t, rep.rows, 1)
	require.Equal(t, "InvalidArgument", rep.rows[0].ErrorCode)
	require.Equal(t, int64(101), c.put, "cursor still advances past skipped row")
}

func TestMemberships_AddMemberPermissionDenied_HardFails(t *testing.T) {
	r := &fakeMemReader{pages: [][]legacy.UserOrganization{sampleMemberships()}}
	tl := tenantOK("tenant-uuid")
	il := identityOK("user-uuid")
	ma := &fakeMembers{errs: []error{status.Error(codes.PermissionDenied, "missing scope")}}
	c := &fakeCursor{}
	rep := &fakeReporter{}
	met := newFakeMetrics()

	sum, err := newMemberships(t, r, tl, il, ma, c, rep, met, false).Run(context.Background())
	require.Error(t, err)
	require.Contains(t, err.Error(), "PERMISSION_DENIED")
	// First row got partway then errored. Summary reflects 1 errored
	// (the row that hard-failed). Cursor put count is 0 — never
	// advances on hard fail.
	require.Equal(t, 1, sum.Errored)
