// --- Fakes ------------------------------------------------------------------

type fakeReader struct {
	org *legacy.Organization
	err error
}

func (f *fakeReader) GetOrganization(_ context.Context, _ int64) (*legacy.Organization, error) {
	return f.org, f.err
}

type fakeTarget struct {
	resp *tenantv1.BootstrapResponse
	errs []error // returned in order; last value sticks
	calls int
	lastReq *tenantv1.BootstrapRequest
}

func (f *fakeTarget) Bootstrap(_ context.Context, req *tenantv1.BootstrapRequest) (*tenantv1.BootstrapResponse, error) {
	f.lastReq = req
	idx := f.calls
	if idx >= len(f.errs) {
		idx = len(f.errs) - 1
	}
	f.calls++
	if idx < 0 || f.errs[idx] == nil {
		return f.resp, nil
	}
	return nil, f.errs[idx]
}

type fakeCursor struct {
	get      int64
	getFound bool
	getErr   error

	put      int64
	putCalls int
	putErr   error
}

func (f *fakeCursor) Get(_ context.Context, _, _, _ string) (int64, bool, error) {
	return f.get, f.getFound, f.getErr
}

func (f *fakeCursor) Put(_ context.Context, _, _, _ string, offset int64) error {
	f.put = offset
	f.putCalls++
	return f.putErr
}

type fakeReporter struct {
	rows []migrator.RejectionEntry
}

func (f *fakeReporter) Write(e migrator.RejectionEntry) error {
	f.rows = append(f.rows, e)
	return nil
}

type fakeMetrics struct {
	planned    int
	applied    map[string]int // result → count
	rejections map[string]int // error_code → count
	lag        int64
	durations  []time.Duration
}

func newFakeMetrics() *fakeMetrics {
	return &fakeMetrics{
		applied:    map[string]int{},
		rejections: map[string]int{},
	}
}

func (f *fakeMetrics) RowsPlanned(context.Context, string, string)              { f.planned++ }
func (f *fakeMetrics) RowsApplied(_ context.Context, _, _, result string)       { f.applied[result]++ }
func (f *fakeMetrics) RecordApplyDuration(_ context.Context, _, _ string, d time.Duration) {
	f.durations = append(f.durations, d)
}
func (f *fakeMetrics) SetLagRows(_ context.Context, _, _ string, n int64)       { f.lag = n }
func (f *fakeMetrics) RejectionsInc(_ context.Context, _, _, code string)       { f.rejections[code]++ }
func (f *fakeMetrics) TokenRefreshInc(context.Context)                          {}

// noSleep recorder — avoids real backoff delays in tests.
func noSleep(context.Context, time.Duration) error { return nil }

