	a, err := apply.NewTenants(apply.TenantsConfig{
		Reader:   fr,
		Target:   ft,
		Cursor:   fc,
		Reporter: fp,
		Metrics:  fm,
		RunID:    "run-test",
		TenantID: 42,
		DryRun:   dryRun,
		Retry:    &apply.RetryPolicy{MaxAttempts: 5, Sleep: noSleep},
	})
	require.NoError(t, err)
