func TestTenants_HappyPath_Created(t *testing.T) {
	fr := &fakeReader{org: sampleOrg()}
	ft := &fakeTarget{resp: &tenantv1.BootstrapResponse{Tenant: &tenantv1.Tenant{Id: "x"}}, errs: []error{nil}}
	fc := &fakeCursor{}
	fp := &fakeReporter{}
	fm := newFakeMetrics()

	sum, err := newTenants(t, fr, ft, fc, fp, fm, false).Run(context.Background())
	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 1, Applied: 1}, sum)
	require.Equal(t, 1, ft.calls)
	require.Equal(t, int64(42), fc.put, "cursor advanced to TenantID on success")
	require.Equal(t, 1, fc.putCalls)
	require.Equal(t, 1, fm.applied["created"])
	require.Equal(t, int64(0), fm.lag)
	require.Empty(t, fp.rows, "no rejection on happy path")
}

func TestTenants_AlreadyExists_Upserted(t *testing.T) {
