	ft := &fakeTarget{errs: []error{status.Error(codes.AlreadyExists, "tenant exists")}}
	fc := &fakeCursor{}
	fp := &fakeReporter{}
	fm := newFakeMetrics()

	sum, err := newTenants(t, fr, ft, fc, fp, fm, false).Run(context.Background())
	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 1, Applied: 1}, sum)
	require.Equal(t, 1, fm.applied["upserted"])
	require.Equal(t, int64(42), fc.put)
