	fr := &fakeReader{org: sampleOrg()}
	ft := &fakeTarget{errs: []error{status.Error(codes.InvalidArgument, "slug invalid")}}
	fc := &fakeCursor{}
	fp := &fakeReporter{}
	fm := newFakeMetrics()

