	require.NoError(t, err)
	require.Equal(t, apply.Summary{Planned: 1, Rejected: 1}, sum)
	require.Equal(t, 1, fm.applied["skipped"])
	require.Equal(t, 1, fm.rejections["InvalidArgument"])
	require.Len(t, fp.rows, 1)
	require.Equal(t, "42", fp.rows[0].LegacyID)
	require.Equal(t, "InvalidArgument", fp.rows[0].ErrorCode)
	require.Equal(t, int64(42), fc.put, "cursor advances on rejection — row will not be retried")
