func TestTenants_PermissionDenied_HardFails(t *testing.T) {
	fr := &fakeReader{org: sampleOrg()}
	ft := &fakeTarget{errs: []error{status.Error(codes.PermissionDenied, "missing migration:write")}}
	fc := &fakeCursor{}
	fp := &fakeReporter{}
