// TenantReader is the slice of internal/legacy.Reader the apply loop
// needs. Defined here so tests inject fakes and don't require a real
// pgx pool.
type TenantReader interface {
	GetOrganization(ctx context.Context, id int64) (*legacy.Organization, error)
}

// TenantTarget is the slice of internal/target.TenantClient the
// tenants apply loop (phase 1) needs.
type TenantTarget interface {
	Bootstrap(ctx context.Context, req *tenantv1.BootstrapRequest) (*tenantv1.BootstrapResponse, error)
}

// MembershipReader is the slice of internal/legacy.Reader the
// memberships apply loop (phase 3) needs.
type MembershipReader interface {
	ListUserOrganizations(ctx context.Context, tenantID, cursor int64, limit int) ([]legacy.UserOrganization, error)
}

// TenantLookup is the slice of internal/target.TenantClient phase 3
// uses to translate a legacy organization_id → new tenant UUID.
type TenantLookup interface {
	GetByLegacyId(ctx context.Context, req *tenantv1.GetByLegacyIdRequest) (*tenantv1.GetByLegacyIdResponse, error)
}

// MembershipAdder is the slice of internal/target.TenantClient phase
// 3 uses to write the resolved (tenant, user, role) tuple.
type MembershipAdder interface {
	AddMember(ctx context.Context, req *tenantv1.AddMemberRequest) (*tenantv1.AddMemberResponse, error)
}

// IdentityLookup is the slice of internal/target.IdentityClient phase
// 3 uses to translate a legacy user_id → new user UUID.
type IdentityLookup interface {
	GetByLegacyId(ctx context.Context, req *userv1.GetByLegacyIdRequest) (*userv1.GetByLegacyIdResponse, error)
}

// CursorBackend matches platform/libs/go/migrator.Cursor's Get/Put
// surface so production passes the real Cursor and tests pass an
// in-memory backend.
type CursorBackend interface {
	Get(ctx context.Context, binary, tenant, entity string) (int64, bool, error)
	Put(ctx context.Context, binary, tenant, entity string, offset int64) error
}

// Reporter matches platform/libs/go/migrator.Rejection's Write
// surface. Tests pass an in-memory recorder; production passes the
// real JSONL writer.
type Reporter interface {
