package apply

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	userv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/identity/user/v1"
	tenantv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/org/tenant/v1"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-org/internal/legacy"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-org/internal/mapper"
)

const entityMemberships = "memberships"

// MembershipsConfig wires the phase-3 orchestrator's deps + behaviour.
type MembershipsConfig struct {
	Reader   MembershipReader
	Tenants  TenantLookup
	Identity IdentityLookup
	Members  MembershipAdder
	Cursor   CursorBackend
	Reporter Reporter
	Metrics  MetricsSink

	RunID     string
	TenantID  int64 // legacy organizations.id
	BatchSize int   // rows per ListUserOrganizations call
	DryRun    bool
	Retry     *RetryPolicy
}

// Memberships is phase 3 of migrator-org cutover: paginate the legacy
// user_organizations table for the configured tenant, resolve each
// row's user/tenant via GetByLegacyId, map role, and call
// org-svc.TenantService.AddMember.
//
// The home-org-skip optimization mentioned in spec §7c is NOT
// implemented in this slice — the server's ALREADY_EXISTS handling
// (idempotent membership upsert) covers the same case correctly,
// just at the cost of one extra RPC per home-org row. If profiling
// shows that's hot, an opt-in pre-skip can land later without
// changing the orchestrator's contract.
type Memberships struct {
	cfg MembershipsConfig
}

// NewMemberships validates config and returns the orchestrator.
func NewMemberships(cfg MembershipsConfig) (*Memberships, error) {
	if cfg.Reader == nil {
		return nil, errors.New("apply: Reader required")
	}
	if cfg.Tenants == nil {
		return nil, errors.New("apply: Tenants lookup required")
	}
	if cfg.Identity == nil {
		return nil, errors.New("apply: Identity lookup required")
	}
	if cfg.Members == nil {
		return nil, errors.New("apply: Members adder required")
	}
	if cfg.Cursor == nil {
		return nil, errors.New("apply: Cursor required")
	}
	if cfg.Reporter == nil {
		return nil, errors.New("apply: Reporter required")
	}
	if cfg.Metrics == nil {
		return nil, errors.New("apply: Metrics required")
	}
	if cfg.TenantID <= 0 {
		return nil, fmt.Errorf("apply: TenantID must be > 0 (got %d)", cfg.TenantID)
	}
	if cfg.BatchSize <= 0 {
		cfg.BatchSize = 100
	}
	if cfg.Retry == nil {
		cfg.Retry = &RetryPolicy{MaxAttempts: 5, Sleep: RealSleep}
	}
	return &Memberships{cfg: cfg}, nil
}

// Run executes phase 3. Loops until ListUserOrganizations returns an
// empty page; each iteration does at most BatchSize rows; cursor
// advances per row so a mid-batch crash resumes cleanly.
func (m *Memberships) Run(ctx context.Context) (Summary, error) {
	tenantStr := strconv.FormatInt(m.cfg.TenantID, 10)
	var sum Summary

	// Resolve the new-stack tenant UUID once at the top — every row
	// targets the same tenant, so cache it.
	tenantUUID, err := m.lookupTenant(ctx, m.cfg.TenantID)
	if err != nil {
		return sum, fmt.Errorf("apply: resolve tenant uuid for legacy %d: %w", m.cfg.TenantID, err)
	}

	// Read the resume point once. The persisted cursor is the "where
	// did the last apply leave off" anchor; from there we walk forward
	// in memory. Persisting per-row to KV is reserved for non-dry-run
	// (plan mode must not poison apply's resume state — see
	// TestMemberships_DryRun_DoesNotAdvanceCursor).
	//
	// Tracking cursor locally also fixes issue #53: previously dry-run
	// re-fetched the same starting cursor every iteration, so the
	// reader returned the same page forever.
	cursor, _, err := m.cfg.Cursor.Get(ctx, binaryName, tenantStr, entityMemberships)
	if err != nil {
		return sum, fmt.Errorf("apply: read cursor: %w", err)
	}

	for {
		rows, err := m.cfg.Reader.ListUserOrganizations(ctx, m.cfg.TenantID, cursor, m.cfg.BatchSize)
		if err != nil {
			return sum, fmt.Errorf("apply: list user_organizations: %w", err)
		}
		if len(rows) == 0 {
			break // phase done
		}

		for _, row := range rows {
			result, perRowErr := m.applyRow(ctx, row, tenantUUID, tenantStr)
			tally(&sum, result)
			if perRowErr != nil {
				// Hard fail aborts the whole loop.
				return sum, perRowErr
			}
			cursor = row.ID
			if !m.cfg.DryRun {
				if putErr := m.cfg.Cursor.Put(ctx, binaryName, tenantStr, entityMemberships, row.ID); putErr != nil {
					return sum, fmt.Errorf("apply: cursor put after row %d: %w", row.ID, putErr)
				}
			}
		}
	}

	m.cfg.Metrics.SetLagRows(ctx, tenantStr, entityMemberships, 0)
	return sum, nil
}

// rowResult is the verdict for a single row, used by tally to
// increment the right Summary field.
type rowResult int

const (
	resultCreated rowResult = iota
	resultUpserted
	resultSkipped
	resultErrored
)

func tally(s *Summary, r rowResult) {
	switch r {
	case resultCreated, resultUpserted:
		s.Applied++
	case resultSkipped:
		s.Rejected++
	case resultErrored:
		s.Errored++
	}
	s.Planned++
}

// applyRow handles one legacy user_organizations row end-to-end:
// resolve user UUID, map, AddMember with retry, dispatch error
// matrix. Returns (result, hardFailErr) — non-nil err aborts the
// whole loop; nil err means continue (even on rejection/error
// results).
func (m *Memberships) applyRow(ctx context.Context, row legacy.UserOrganization, tenantUUID, tenantStr string) (rowResult, error) {
	m.cfg.Metrics.RowsPlanned(ctx, tenantStr, entityMemberships)

	// Resolve user UUID. NOT_FOUND on user is the canonical
	// "phase 2 incomplete" signal per spec §7a — write to rejection
	// report, advance, continue.
	userResp, err := m.cfg.Identity.GetByLegacyId(ctx, &userv1.GetByLegacyIdRequest{
		LegacyId: &commonv1.LegacyID{Value: strconv.FormatInt(row.UserID, 10)},
	})
	if err != nil {
		st, _ := status.FromError(err)
		if st.Code() == codes.NotFound {
			m.writeRejection(row, "USER_NOT_MIGRATED", st.Message())
			m.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityMemberships, "USER_NOT_MIGRATED")
			m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "skipped")
			return resultSkipped, nil
		}
		// Any other error on lookup is a hard fail (transient errors
		// would have been retried by the lookup wrapper if it had
		// retry logic; for now the lookup is single-shot and we
		// surface).
		m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "errored")
		return resultErrored, fmt.Errorf("apply: identity lookup user_id=%d: %w", row.UserID, err)
	}
	userUUID := userResp.GetUser().GetId()

	// Map row → AddMemberRequest.
	req, err := mapper.Membership(row, tenantUUID, userUUID, m.cfg.DryRun)
	if err != nil {
		m.writeRejection(row, "MAPPER_VALIDATION", err.Error())
		m.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityMemberships, "MAPPER_VALIDATION")
		m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "skipped")
		return resultSkipped, nil
	}

	// AddMember with retry.
	startedAt := time.Now()
	var verdict rowResult
	addErr := WithBackoff(ctx, *m.cfg.Retry, func() (RetryDecision, error) {
		_, callErr := m.cfg.Members.AddMember(ctx, req)
		if callErr == nil {
			verdict = resultCreated
			return RetryDecisionDone, nil
		}
		st, ok := status.FromError(callErr)
		if !ok {
			return RetryDecisionRetry, callErr
		}
		switch st.Code() {
		case codes.OK:
			verdict = resultCreated
			return RetryDecisionDone, nil
		case codes.AlreadyExists:
			verdict = resultUpserted
			return RetryDecisionDone, nil
		case codes.InvalidArgument:
			verdict = resultSkipped
			m.writeRejection(row, st.Code().String(), st.Message())
			m.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityMemberships, st.Code().String())
			return RetryDecisionDone, nil
		case codes.PermissionDenied:
			return RetryDecisionHardFail,
				fmt.Errorf("apply: PERMISSION_DENIED on AddMember (check migration:write scope): %w", callErr)
		case codes.Unavailable, codes.DeadlineExceeded:
			return RetryDecisionRetry, callErr
		default:
			return RetryDecisionHardFail, callErr
		}
	})
	m.cfg.Metrics.RecordApplyDuration(ctx, tenantStr, entityMemberships, time.Since(startedAt))
	if addErr != nil {
		m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "errored")
		return resultErrored, addErr
	}

	switch verdict {
	case resultCreated:
		m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "created")
	case resultUpserted:
		m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "upserted")
	case resultSkipped:
		m.cfg.Metrics.RowsApplied(ctx, tenantStr, entityMemberships, "skipped")
	}
	return verdict, nil
}

// lookupTenant resolves the legacy organization_id → new tenant UUID
// at startup. Phase 3 only ever migrates one tenant per run, so this
// is a single RPC per process.
func (m *Memberships) lookupTenant(ctx context.Context, legacyTenantID int64) (string, error) {
	resp, err := m.cfg.Tenants.GetByLegacyId(ctx, &tenantv1.GetByLegacyIdRequest{
		LegacyId: &commonv1.LegacyID{Value: strconv.FormatInt(legacyTenantID, 10)},
	})
	if err != nil {
		return "", err
	}
	id := resp.GetTenant().GetId()
	if id == "" {
		return "", fmt.Errorf("apply: tenant lookup returned empty UUID for legacy %d (phase 1 incomplete?)", legacyTenantID)
	}
	return id, nil
}

func (m *Memberships) writeRejection(row legacy.UserOrganization, code, msg string) {
	_ = m.cfg.Reporter.Write(migrator.RejectionEntry{
		LegacyID:  strconv.FormatInt(row.ID, 10),
		Entity:    entityMemberships,
		ErrorCode: code,
		ErrorMsg:  msg,
		Timestamp: time.Now(),
	})
}


