// cursorMemReader mirrors the real legacy.Reader's cursor semantics
// (rows whose ID is strictly greater than `cursor`, in ID order,
// capped at `limit`). The default fakeMemReader ignores the cursor,
// which hides the issue #53 plan-mode infinite loop.
type cursorMemReader struct {
	rows  []legacy.UserOrganization
	calls int
}

