// Package apply orchestrates the legacy → target migration loop.
//
// The package is deliberately interface-driven (see interfaces.go):
// the orchestrator depends on Reader, Target, Cursor, Reporter, and
// Metrics interfaces, so unit tests inject in-memory fakes and the
// state-machine logic exercises the full §9 error matrix without any
// real network or database. Production wires real implementations
// from internal/legacy, internal/target, and platform/libs/go/migrator.
package apply

import (
	"context"
	"time"
)

// RetryDecision is the verdict the operation function returns to
// WithBackoff. Done means success — no further attempts. Retry means
// transient failure — wait and try again. HardFail means terminal —
// surface the error immediately, no further attempts.
type RetryDecision int

const (
	// RetryDecisionDone — operation succeeded; stop.
	RetryDecisionDone RetryDecision = iota
	// RetryDecisionRetry — transient failure; sleep then try again
	// up to RetryPolicy.MaxAttempts.
	RetryDecisionRetry
	// RetryDecisionHardFail — terminal failure (e.g.,
	// PERMISSION_DENIED); abort the loop immediately.
	RetryDecisionHardFail
)

// RetryPolicy configures WithBackoff.
type RetryPolicy struct {
	// MaxAttempts caps the total number of operation attempts (not
	// retries). Per spec §9 this is 5 for UNAVAILABLE handling.
	// Values < 1 are treated as 1 — degenerate input still runs the
	// operation once so callers don't get silent no-op success.
	MaxAttempts int

	// Sleep is the test seam for the backoff delays. Production
	// passes a function backed by time.Sleep + ctx.Done(); tests
	// pass a recorder that doesn't actually wait. Returning a
	// non-nil error from Sleep aborts the retry chain.
	Sleep func(ctx context.Context, d time.Duration) error
}

// WithBackoff invokes op() repeatedly with exponential backoff
// (1s, 2s, 4s, 8s, 16s — capped at MaxAttempts attempts total).
//
// The schedule matches spec §9 ("UNAVAILABLE: backoff retry
// 1s/2s/4s/8s/16s; after 5 attempts hard fail"). Decisions are
// returned by op so the apply orchestrator can map gRPC status codes
// to the right action without leaking grpc imports into this package.
func WithBackoff(ctx context.Context, p RetryPolicy, op func() (RetryDecision, error)) error {
	attempts := p.MaxAttempts
	if attempts < 1 {
		attempts = 1
	}

	delay := time.Second
	var lastErr error
	for i := 0; i < attempts; i++ {
		decision, err := op()
		switch decision {
		case RetryDecisionDone:
			return nil
		case RetryDecisionHardFail:
			return err
		case RetryDecisionRetry:
			lastErr = err
			if i == attempts-1 {
				// Final attempt; don't sleep, just surface the error.
				return lastErr
			}
			if sleepErr := p.Sleep(ctx, delay); sleepErr != nil {
				return sleepErr
			}
			delay *= 2
		}
	}
	return lastErr
}

// RealSleep is a Sleep implementation backed by time.After + ctx.Done().
// Production wires this; tests pass recorders.
func RealSleep(ctx context.Context, d time.Duration) error {
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}


