	err := apply.WithBackoff(context.Background(), apply.RetryPolicy{
		MaxAttempts: 5,
		Sleep: func(_ context.Context, d time.Duration) error {
			sleeps = append(sleeps, d)
			return nil
		},
	}, func() (apply.RetryDecision, error) {
		calls++
		return apply.RetryDecisionRetry, errors.New("permanently down")
	})

	require.Error(t, err)
	require.Contains(t, err.Error(), "permanently down")
	require.Equal(t, 5, calls, "MaxAttempts=5 means 5 calls total")
	require.Equal(t, []time.Duration{
		1 * time.Second,
		2 * time.Second,
		4 * time.Second,
		8 * time.Second,
	}, sleeps, "4 sleeps between 5 attempts")
}

func TestWithBackoff_HardFailStopsImmediately(t *testing.T) {
	calls := 0
	sleeps := []time.Duration{}

	wantErr := errors.New("PERMISSION_DENIED")
	err := apply.WithBackoff(context.Background(), apply.RetryPolicy{
		MaxAttempts: 5,
		Sleep: func(_ context.Context, d time.Duration) error {
			sleeps = append(sleeps, d)
			return nil
		},
	}, func() (apply.RetryDecision, error) {
		calls++
		return apply.RetryDecisionHardFail, wantErr
	})

	require.ErrorIs(t, err, wantErr)
	require.Equal(t, 1, calls)
	require.Empty(t, sleeps, "hard-fail must abort without backoff")
}

func TestWithBackoff_HonorsContextCancel(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())

	err := apply.WithBackoff(ctx, apply.RetryPolicy{
		MaxAttempts: 5,
		Sleep: func(c context.Context, d time.Duration) error {
			return c.Err() // bail when ctx is canceled
		},
	}, func() (apply.RetryDecision, error) {
		cancel() // cancel mid-flight after first call
		return apply.RetryDecisionRetry, errors.New("x")
	})

	require.Error(t, err)
	require.ErrorIs(t, err, context.Canceled,
		"backoff sleep must bail when ctx is cancelled")
}

func TestWithBackoff_ZeroMaxAttemptsDefaultsToOne(t *testing.T) {
	calls := 0
	err := apply.WithBackoff(context.Background(), apply.RetryPolicy{
		MaxAttempts: 0,
		Sleep:       func(context.Context, time.Duration) error { return nil },
	}, func() (apply.RetryDecision, error) {
		calls++
		return apply.RetryDecisionRetry, errors.New("x")
	})
	require.Error(t, err)
	require.Equal(t, 1, calls,
		"degenerate MaxAttempts=0 must still try once so caller never gets a no-op success")
}


