package apply

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-org/internal/legacy"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-org/internal/mapper"
)

const (
	binaryName    = "migrator-org"
	entityTenants = "tenants"
)

// Summary is the per-run report the orchestrator returns to the
// caller (cmd/server/main.go), which prints it to stderr at end of
// run. Operators read these counts as the cutover go/no-go signal
// alongside the rejection report file.
type Summary struct {
	Planned  int // rows the legacy reader produced (1 for phase 1's single-tenant query)
	Applied  int // rows that landed successfully (created OR upserted) in apply mode
	Rejected int // rows skipped due to INVALID_ARGUMENT (or other recoverable errors)
	Errored  int // rows that hit an unexpected error path
}

// TenantsConfig wires the orchestrator's dependencies + behaviour
// flags. Apart from DryRun, all dependencies are required.
type TenantsConfig struct {
	Reader   TenantReader
	Target   TenantTarget
	Cursor   CursorBackend
	Reporter Reporter
	Metrics  MetricsSink
	RunID    string

	// TenantID is the legacy organizations.id matching MIGRATOR_TENANT_FILTER.
	TenantID int64

	// DryRun toggles plan vs apply mode. When true, the row is read,
	// mapped, and the request sent with dry_run=true so the server
	// validates without writing. Cursor is NOT advanced in dry-run
	// (next run still produces a plan output).
	DryRun bool

	// Retry overrides the default exponential-backoff policy. nil
	// uses the spec's default (1/2/4/8/16s; max 5 attempts) backed
	// by RealSleep.
	Retry *RetryPolicy
}

// Tenants is phase 1 of the migrator-org cutover: read one legacy
// organizations row, map it, call org-svc.TenantService.Bootstrap.
type Tenants struct {
	cfg TenantsConfig
}

// NewTenants validates the config and returns the orchestrator.
func NewTenants(cfg TenantsConfig) (*Tenants, error) {
	if cfg.Reader == nil {
		return nil, errors.New("apply: Reader required")
	}
	if cfg.Target == nil {
		return nil, errors.New("apply: Target required")
	}
	if cfg.Cursor == nil {
		return nil, errors.New("apply: Cursor required")
	}
	if cfg.Reporter == nil {
		return nil, errors.New("apply: Reporter required")
	}
	if cfg.Metrics == nil {
		return nil, errors.New("apply: Metrics required")
	}
	if cfg.TenantID <= 0 {
		return nil, fmt.Errorf("apply: TenantID must be > 0 (got %d)", cfg.TenantID)
	}
	if cfg.Retry == nil {
		cfg.Retry = &RetryPolicy{MaxAttempts: 5, Sleep: RealSleep}
	}
	return &Tenants{cfg: cfg}, nil
}

// Run executes phase 1 against the configured tenant filter.
//
// State-machine outline (per spec §6):
//
//  1. Read cursor. If equal to TenantID, this run is a no-op replay —
//     return summary{} with no metrics emitted.
//  2. Read legacy organizations row. If not present, return
//     summary{Planned:0} (operator interprets as "tenant absent
//     from legacy snapshot").
//  3. Map row → BootstrapRequest with DryRun toggle.
//  4. Call target.Bootstrap, wrapped in WithBackoff for §9 transient
//     handling.
//  5. Map response → result code:
//       OK                    → result=created (or upserted if the
//                                server marked it so via dry_run_planned
//                                semantics; collapsed to "created"
//                                here for now)
//       INVALID_ARGUMENT      → write rejection report; advance cursor;
//                                emit RejectionsInc; result=skipped.
//       ALREADY_EXISTS        → idempotent replay; advance cursor;
//                                result=upserted.
//       PERMISSION_DENIED     → hard fail with the original error.
//       UNAVAILABLE           → handled inside WithBackoff via Retry.
//  6. Emit metrics (RowsPlanned, RowsApplied, ApplyDuration).
//  7. Update lag (rows remaining = 1 if not yet applied, 0 after).
//  8. Return summary.
func (t *Tenants) Run(ctx context.Context) (Summary, error) {
	tenantStr := strconv.FormatInt(t.cfg.TenantID, 10)
	var sum Summary

	// Step 1: cursor check.
	cur, found, err := t.cfg.Cursor.Get(ctx, binaryName, tenantStr, entityTenants)
	if err != nil {
		return sum, fmt.Errorf("apply: read cursor: %w", err)
	}
	if found && cur == t.cfg.TenantID && !t.cfg.DryRun {
		// Already applied. No-op, lag=0.
		t.cfg.Metrics.SetLagRows(ctx, tenantStr, entityTenants, 0)
		return sum, nil
	}

	// Step 2: read the legacy row.
	org, err := t.cfg.Reader.GetOrganization(ctx, t.cfg.TenantID)
	if err != nil {
		return sum, fmt.Errorf("apply: read legacy organization %d: %w", t.cfg.TenantID, err)
	}
	if org == nil {
		// Not present in legacy. Surface 0/0/0 — operator sees that
		// as "tenant absent."
		t.cfg.Metrics.SetLagRows(ctx, tenantStr, entityTenants, 0)
		return sum, nil
	}
	sum.Planned = 1
	t.cfg.Metrics.RowsPlanned(ctx, tenantStr, entityTenants)
	t.cfg.Metrics.SetLagRows(ctx, tenantStr, entityTenants, 1)

	// Step 3: map.
	req, err := mapper.Tenant(*org, t.cfg.DryRun)
	if err != nil {
		// Mapper validation failure — record as rejection and stop.
		t.cfg.Reporter.Write(rejectionFromMapper(t.cfg.RunID, *org, err))
		t.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityTenants, "MAPPER_VALIDATION")
		sum.Rejected = 1
		t.cfg.Metrics.SetLagRows(ctx, tenantStr, entityTenants, 0)
		return sum, nil
	}

	// Steps 4–6: apply with retry + error matrix.
	startedAt := time.Now()
	var result string
	err = WithBackoff(ctx, *t.cfg.Retry, func() (RetryDecision, error) {
		_, callErr := t.cfg.Target.Bootstrap(ctx, req)
		if callErr == nil {
			result = "created"
			return RetryDecisionDone, nil
		}
		st, ok := status.FromError(callErr)
		if !ok {
			// Non-gRPC error (rare) — treat as transient.
			return RetryDecisionRetry, callErr
		}
		switch st.Code() {
		case codes.OK:
			result = "created"
			return RetryDecisionDone, nil
		case codes.AlreadyExists:
			result = "upserted"
			return RetryDecisionDone, nil
		case codes.InvalidArgument:
			result = "skipped"
			t.cfg.Reporter.Write(rejectionFromTarget(t.cfg.RunID, *org, st))
			t.cfg.Metrics.RejectionsInc(ctx, tenantStr, entityTenants, st.Code().String())
			return RetryDecisionDone, nil
		case codes.PermissionDenied:
			return RetryDecisionHardFail,
				fmt.Errorf("apply: PERMISSION_DENIED — check migration:write scope on the migrator service-account: %w", callErr)
		case codes.Unavailable, codes.DeadlineExceeded:
			return RetryDecisionRetry, callErr
		default:
			// Unknown gRPC code — surface to caller without retrying.
			return RetryDecisionHardFail, callErr
		}
	})
	t.cfg.Metrics.RecordApplyDuration(ctx, tenantStr, entityTenants, time.Since(startedAt))
	if err != nil {
		sum.Errored = 1
		t.cfg.Metrics.RowsApplied(ctx, tenantStr, entityTenants, "errored")
		return sum, err
	}

	// Step 7: tally + cursor advance + metrics.
	switch result {
	case "skipped":
		sum.Rejected = 1
		// Skipped advances cursor too — the row is not retried.
		if !t.cfg.DryRun {
			if err := t.cfg.Cursor.Put(ctx, binaryName, tenantStr, entityTenants, t.cfg.TenantID); err != nil {
				return sum, fmt.Errorf("apply: cursor put after skip: %w", err)
			}
		}
		t.cfg.Metrics.RowsApplied(ctx, tenantStr, entityTenants, "skipped")
	case "created", "upserted":
		sum.Applied = 1
		if !t.cfg.DryRun {
			if err := t.cfg.Cursor.Put(ctx, binaryName, tenantStr, entityTenants, t.cfg.TenantID); err != nil {
				return sum, fmt.Errorf("apply: cursor put: %w", err)
			}
		}
		t.cfg.Metrics.RowsApplied(ctx, tenantStr, entityTenants, result)
	}
	t.cfg.Metrics.SetLagRows(ctx, tenantStr, entityTenants, 0)
	return sum, nil
}

func rejectionFromMapper(runID string, o legacy.Organization, err error) migrator.RejectionEntry {
	return migrator.RejectionEntry{
		LegacyID:  strconv.FormatInt(o.ID, 10),
		Entity:    entityTenants,
		ErrorCode: "MAPPER_VALIDATION",
		ErrorMsg:  err.Error(),
		Timestamp: time.Now(),
	}
}

func rejectionFromTarget(runID string, o legacy.Organization, st *status.Status) migrator.RejectionEntry {
	return migrator.RejectionEntry{
		LegacyID:  strconv.FormatInt(o.ID, 10),
		Entity:    entityTenants,
		ErrorCode: st.Code().String(),
		ErrorMsg:  st.Message(),
		Timestamp: time.Now(),
	}
}


